6	import { startServer, type StartedServer } from '../testing/server.ts';
7	
8	// 读取兼容的回归保障：保护「已经保存的意见只按结构完整性读取，不重新套用新提交的内容限制」
9	// 这一现有行为。新意见的提交规则仍由接口与首页的内容校验约束（标题去首尾空白后非空、
10	// 最多 120 码点；详细说明含非空白内容、最多 5000 码点；使用场景最多 1000 码点），
11	// 但这些规则只能作用于新提交，读取历史记录时不能再套一遍——否则上限或空白要求一旦变化，
12	// 旧意见就会在列表接口变成整次加载失败。
13	//
14	// 本文件真实起一份 server.ts，启动前直接把「按今天的规则已无法提交、但记录结构完整」的
15	// 历史数据写入 ideas.json，只走公开的 GET/POST /api/ideas，覆盖：
16	//   - 标题/详细说明/使用场景超过当前上限、标题或详细说明只有空白的历史记录仍 200 返回，
17	//     长内容不截断、空白不替换为默认文字，首尾空白、换行、中文、表情与标记样文本逐字保留；
18	//   - scenario 为空字符串是正常记录（与缺少 scenario 字段不同），同样原样读取；
19	//   - 读取完成后再提交一条符合当前规则的新意见：201 且排在旧意见之前，
20	//     旧记录的内容、标识、时间与相对次序保持不变，SIGTERM 重启后仍然如此；
21	//   - 同样的超限或空白内容作为新意见提交时仍返回 400 字段错误，旧记录不受影响——
22	//     新旧内容的区别必须保留；
23	//   - 结构判定不能为了接受超限旧内容而放宽：混入缺字段或字段类型错误的记录时，
24	//     即使其中夹着结构完整的超限记录，整次读取仍 500 失败，磁盘内容逐字节保留。
25	
26	interface Idea {
27	  id: string;
28	  title: string;
29	  description: string;
30	  scenario: string;
31	  createdAt: string;
32	}
33	
34	const TITLE_LIMIT = 120;
35	const DESCRIPTION_LIMIT = 5000;
36	const SCENARIO_LIMIT = 1000;
37	const points = (text: string): number => Array.from(text).length;
38	const repeatCp = (char: string, times: number): string => char.repeat(times);
39	
40	// 一组按今天的提交规则已无法新建、但结构完整的历史记录，刻意夹着一条普通意见，
41	// 用来证明读取时不会跳过内容特殊的记录、也不会只返回混在其中的普通意见。
42	// 磁盘上的数组次序就是接口返回次序（最新在前由写入方保证，读取方不重排）。
43	function legacyIdeas(): Idea[] {
44	  return [
45	    {
46	      id: 'legacy-over-title-0001',
47	      // 标题超过当前上限一个码点，且含首尾空白（历史标题不去空白、不截断）
48	      title: '  ' + repeatCp('长', TITLE_LIMIT + 1) + ' ',
49	      description: '标题超限历史记录的正文\n第二行保留换行 与中文😀',
50	      scenario: '标题超限记录的场景',
51	      createdAt: '2020-01-01T00:00:00.000Z',
52	    },
53	    {
54	      id: 'legacy-over-desc-0002',
55	      title: '正文超限的历史意见',
56	      // 详细说明恰好超过当前上限一个码点：5000 个中文 + 单个 😀
57	      description: repeatCp('描', DESCRIPTION_LIMIT) + '😀',
58	      scenario: '正文超限记录的场景 🌙',
59	      createdAt: '2020-02-02T00:02:00.000Z',
60	    },
61	    {
62	      id: 'legacy-over-scenario-0003',
63	      title: '  场景超限且标题首尾空白保留  ',
64	      description: '场景超限历史记录的正文',
65	      // 使用场景超过当前上限一个码点
66	      scenario: repeatCp('景', SCENARIO_LIMIT + 1),
67	      createdAt: '2020-03-03T00:03:00.000Z',
68	    },
69	    {
