79	      // 标题是空字符串与只有空白的两种边界之一：只有空白（空字符串另由 blank-title-empty 覆盖）
80	      title: '  \t\n ',
81	      description: '标题只有空白的历史正文，必须按原文读到，不能替换成默认标题',
82	      scenario: '空白标题记录的场景',
83	      createdAt: '2020-05-05T00:05:00.000Z',
84	    },
85	    {
86	      id: 'legacy-blank-desc-0006',
87	      title: '正文只有空白的历史意见',
88	      // 详细说明只有空白（含换行）：不能替换成默认正文，也不能判为读取失败
89	      description: '  \n\t  ',
90	      scenario: '',
91	      createdAt: '2020-06-06T00:06:00.000Z',
92	    },
93	    {
94	      id: 'legacy-markup-0007',
95	      // 标题首尾空白 + 尖括号/标记样文本：按普通文字读取，不解释成网页结构
96	      title: '  建议 <b>重点</b> 支持深色模式 😀  ',
97	      description: [
98	        '正文第一行保留换行',
99	        '脚本样文本 <script>alert("x")</script> 与实体原文 &lt;div&gt; &amp;',
100	        '末行含中文、表情与空白  😀  ',
101	      ].join('\n'),
102	      // scenario 为空字符串：正常记录，读取时原样保留为空，不能与缺少 scenario 字段混淆
103	      scenario: '',
104	      createdAt: 'not-a-date-but-a-string',
105	    },
106	    {
107	      id: 'legacy-empty-title-0008',
108	      // 标题就是空字符串：结构完整（字段存在且为字符串）即读取成功
109	      title: '',
110	      description: '标题为空字符串的历史正文',
111	      scenario: '空标题记录的场景',
112	      createdAt: '2020-08-08T00:08:00.000Z',
113	    },
114	    {
115	      id: 'legacy-empty-desc-0009',
116	      title: '正文为空字符串的历史意见',
117	      description: '',
118	      scenario: '空正文记录的场景\n第二行换行保留',
119	      createdAt: '2020-09-09T00:09:00.000Z',
120	    },
121	  ];
122	}
123	
124	function freshDir(): string {
125	  return mkdtempSync(join(tmpdir(), 'featureharbor-legacy-'));
126	}
127	
128	async function getIdeas(
129	  server: StartedServer,
130	): Promise<{ status: number; data: any }> {
131	  const res = await fetch(`${server.origin}/api/ideas`);
132	  return { status: res.status, data: await res.json() };
133	}
134	
135	async function postIdea(
136	  server: StartedServer,
137	  body: unknown,
138	): Promise<{ status: number; data: any }> {
139	  const res = await fetch(`${server.origin}/api/ideas`, {
140	    method: 'POST',
