147	async function safeStop(server: StartedServer | undefined): Promise<void> {
148	  if (!server) return;
149	  await Promise.race([
150	    server.stop(),
151	    new Promise<void>((resolve) => setTimeout(resolve, 2000)),
152	  ]);
153	}
154	
155	// 预置结构完整但内容不符合当前提交限制的历史数据后启动服务
156	async function startWithLegacy(dir: string, ideas: Idea[]): Promise<StartedServer> {
