169	  const dir = freshDir();
170	  const old = legacyIdeas();
171	  let server: StartedServer | undefined;
172	  try {
173	    server = await startWithLegacy(dir, old);
174	
175	    const listed = await getIdeas(server);
176	    assert.equal(listed.status, 200);
177	    assert.ok(Array.isArray(listed.data.ideas));
178	    // 特殊记录一条都不能少，也不能只返回混在其中的普通意见
179	    assert.equal(listed.data.ideas.length, old.length);
180	    assert.deepEqual(listed.data.ideas, old);
181	
182	    // 按 id 取记录，钉住关键内容：长内容完整保留（不截断到当前上限），
183	    // 空白内容不被替换成默认文字，首尾空白与换行、中文、表情逐字保留
184	    const byId = new Map<string, Idea>(
