201	    assert.equal(overScenario.title, '  场景超限且标题首尾空白保留  ');
202	
203	    assert.equal(byId.get('legacy-blank-title-0005')!.title, '  \t\n ');
204	    assert.equal(byId.get('legacy-blank-desc-0006')!.description, '  \n\t  ');
