211	    assert.ok(markup.description.includes('<script>alert("x")</script>'));
212	    assert.ok(markup.description.includes('&lt;div&gt; &amp;'));
213	    assert.equal(markup.scenario, '');
214	    assert.equal(markup.createdAt, 'not-a-date-but-a-string');
215	
216	    // 再查一次，结果稳定一致，读取不能有任何改写副作用
217	    assert.deepEqual((await getIdeas(server)).data.ideas, old);
218	  } finally {
219	    await safeStop(server);
220	    rmSync(dir, { recursive: true, force: true });
221	  }
222	});
223	
224	test('读取历史记录后提交符合当前规则的新意见：201 并排最前，旧记录的内容、标识、时间与相对次序不变（重启后仍一致）', async () => {
