259	  }
260	});
261	
262	test('新旧内容区别保留：超限或空白内容作为新意见提交仍返回 400 字段错误，历史记录数量、次序与内容不变', async (t) => {
263	  const cases: Array<{ name: string; body: Record<string, unknown>; field: string }> = [
264	    {
265	      name: '标题超过 120 码点的新提交被拒',
266	      field: '标题',
267	      body: { title: repeatCp('新', TITLE_LIMIT + 1), description: '说明', scenario: '场景' },
268	    },
269	    {
